  3	/// A move the runner does not offer, in one sentence (spec §11 TU-8 (2), (6)).
  4	struct TutorialRefusal: Error {
  5	    let sentence: String
  6	}
  7	
  8	/// How a step was left: its wait met, Next, or Skip.
  9	enum TutorialAdvance: String {
 10	    case wait, next, skip
 11	}
 12	
 13	/// How a step was entered. A forward entry — start, Next, Skip, a met wait —
 14	/// is a trigger; a Back entry is not (spec §11 TU-8 (3)).
 15	enum TutorialEntry {
 16	    case forward, back
 17	}
 18	
 19	/// What the last Show Me did (spec §11 TU-9).
 20	struct TutorialShowMeOutcome {
 21	    let step: Int
 22	    let ok: Bool
 23	    let error: String?
 24	    /// Each call's result text, in order.
 25	    let results: [String]
 26	    /// The files an `export` call was sent to write.
 27	    let paths: [String]
 28	}
 29	
 30	/// One tutorial running in one editor window, with no chrome (spec §11
 31	/// TU-8): its needs checked at the start, each step's baseline and reveal as
 32	/// it begins, its wait read after events, and Back, Skip, Next, Exit and Show
 33	/// Me (`TutorialShowMe.swift`, TU-9). The panel that shows it is TU3's; the
 34	/// dev tools (`AgentServer+Tutorials.swift`) drive it until then.
 35	///
 36	/// **Event-driven.** A committed document or view-state change
 37	/// (`documentDidChange`, from the editor's `projectDidChange`), a playhead
 38	/// move (`trigger`, from `inspectorPlayheadMoved`), a rate change, the
 39	/// window's sheet beginning or ending, an export started and a forward step
 40	/// entry each call `trigger()`, which schedules ONE coalesced evaluation on
 41	/// the next main turn — a documented `DispatchQueue.main.async` seam — so the
 42	/// event that met a wait has finished first. Nothing polls. While a Show Me
 43	/// runs every evaluation is held, and one runs after its last entry.
 44	///
 45	/// Owned by `EditorViewController.tutorialRunner`; Exit sets that to nil and
 46	/// undoes nothing, and closing the window ends it. Main only.
 47	final class TutorialRunner {
 48	    let tutorial: Tutorial
 49	    weak var editor: EditorViewController?
 50	    weak var document: ProjectDocument?
 51	
 52	    /// The current step's index, 0-based; the last step's once finished.
 53	    private(set) var index = 0
 54	    private(set) var finished = false
 55	    private var baseline: TutorialBaseline
 56	    /// `$created` now: the ids added by the latest step, or Show Me call,
 57	    /// that added any.
 58	    var created: [UInt32] = []
 59	    /// `created` as each step began, so Back restores it.
 60	    private var createdAtBegin: [Int: [UInt32]] = [:]
 61	    private var latches = TutorialLatches()
 62	    private var revealRefused: String?
 63	    private var completed: [(step: Int, by: TutorialAdvance)] = []
 64	    private var evaluationPending = false
 65	    private var observers: [NSObjectProtocol] = []
 66	
 67	    // Show Me's state (`TutorialShowMe.swift`).
 68	    /// True from the press until the last entry's answer is back.
 69	    var showMeRunning = false
 70	    /// A trigger arrived while a Show Me ran.
 71	    var heldEvaluation = false
 72	    /// The Show Me in flight; its generation drops a stale completion.
 73	    var showMeRun: TutorialShowMeRun?
 74	    var showMeGeneration = 0
 75	    var lastShowMe: TutorialShowMeOutcome?
 76	
 77	    private init(tutorial: Tutorial, editor: EditorViewController, document: ProjectDocument) {
 78	        self.tutorial = tutorial
 79	        self.editor = editor
 80	        self.document = document
 81	        baseline = TutorialBaseline(document: document)
 82	    }
 83	
 84	    deinit {
 85	        for observer in observers { NotificationCenter.default.removeObserver(observer) }
 86	        TutorialWait.forgetClipJSON()
 87	    }
 88	
 89	    // MARK: - Start and exit
 90	
 91	    /// Starts `tutorial` in `editor`'s window, replacing any running there;
 92	    /// refused, starting nothing, when its needs are unmet.
 93	    @discardableResult
 94	    static func start(_ tutorial: Tutorial, in editor: EditorViewController) throws
 95	        -> TutorialRunner {
 96	        guard let document = editor.document else {
 97	            throw TutorialRefusal(sentence: "This window has no project.")
 98	        }
 99	        if let sentence = TutorialWait.needsSentence(
100	            tutorial.needs, in: document.editedProject.snapshot)
101	        {
102	            throw TutorialRefusal(sentence: sentence)
103	        }
104	        let runner = TutorialRunner(tutorial: tutorial, editor: editor, document: document)
105	        editor.tutorialRunner = runner
106	        runner.observeSheets(editor.view.window)
107	        runner.begin(0, .forward)
108	        return runner
109	    }
110	
111	    /// Ends the tutorial; the project and its undo history stay as they are.
112	    func exit() {
113	        guard let editor, editor.tutorialRunner === self else { return }
114	        editor.tutorialRunner = nil
115	    }
116	
117	    private func observeSheets(_ window: NSWindow?) {
118	        guard let window else { return }
119	        for name in [NSWindow.willBeginSheetNotification, NSWindow.didEndSheetNotification] {
120	            observers.append(
121	                NotificationCenter.default.addObserver(forName: name, object: window, queue: nil) {
122	                    [weak self] _ in self?.trigger()
123	                })
124	        }
125	    }
126	
127	    // MARK: - Triggers
128	
129	    /// Schedules one evaluation on the next main turn, or holds it while a
130	    /// Show Me runs.
131	    func trigger() {
132	        if showMeRunning {
133	            heldEvaluation = true
134	            return
135	        }
136	        guard !evaluationPending else { return }
137	        evaluationPending = true
138	        DispatchQueue.main.async { [weak self] in self?.evaluate() }
139	    }
140	
141	    /// A committed change or a view-state change; a live tick is ignored.
142	    func documentDidChange(isLive: Bool) {
143	        guard !isLive else { return }
144	        trigger()
145	    }
146	
147	    func playbackRateChanged(_ rate: Float) {
148	        if rate != 0 { latches.playing = true }
149	        trigger()
150	    }
151	
152	    /// The sheet's Export… or Add to Queue, or the `export` tool, started one.
153	    func noteExportStarted() {
154	        latches.exportStarted = true
155	        trigger()
156	    }
157	
158	    private func evaluate() {
159	        evaluationPending = false
160	        if showMeRunning {
161	            heldEvaluation = true
162	            return
163	        }
164	        guard !finished, let editor, editor.tutorialRunner === self, let document else { return }
165	        let step = currentStep
166	        guard !step.wait.isEmpty,
167	              TutorialWait.met(
168	                step.wait, baseline: baseline, created: created, latches: latches,
169	                document: document, window: editor.view.window)
170	        else { return }
171	        advance(by: .wait)
172	    }
173	
174	    // MARK: - Navigation
175	
176	    var currentStep: TutorialStep { tutorial.steps[index] }
177	
178	    /// `$selection`: the step's start selection, in time order.
179	    var selectionAtStart: [UInt32] { baseline.selection }
180	
181	    /// Begins step `next`: its baseline, then its reveal; a forward entry is
182	    /// a trigger.
183	    private func begin(_ next: Int, _ entry: TutorialEntry) {
184	        index = next
185	        finished = false
186	        switch entry {
187	        case .forward: createdAtBegin[next] = created
188	        case .back: created = createdAtBegin[next] ?? created
189	        }
190	        if let document { baseline = TutorialBaseline(document: document) }
191	        latches = TutorialLatches()
192	        revealRefused = nil
193	        if let reveal = currentStep.reveal {
194	            if let inspector = editor?.inspector, inspector.isViewLoaded {
195	                revealRefused = inspector.reveal(reveal)
196	            } else {
197	                revealRefused = "The window has no inspector."
198	            }
199	        }
200	        if entry == .forward { trigger() }
201	    }
202	
203	    private func advance(by how: TutorialAdvance) {
204	        completed.append((index + 1, how))
205	        if let document {
206	            let snapshot = document.editedProject.snapshot
207	            let added = snapshot.clips.map(\.id).filter { !baseline.clipIDs.contains($0) }
208	            if !added.isEmpty { created = TutorialVariables.timeOrdered(added, in: snapshot) }
209	        }
210	        if index + 1 < tutorial.steps.count {
211	            begin(index + 1, .forward)
212	        } else {
213	            finished = true
214	        }
215	    }
216	
217	    private func refuseWhileShowMe() throws {
218	        if showMeRunning { throw TutorialRefusal(sentence: "Show Me is still running.") }
219	    }
220	
221	    func next() throws {
222	        try refuseWhileShowMe()
223	        if finished { throw TutorialRefusal(sentence: "The tutorial is finished.") }
224	        guard currentStep.wait.isEmpty else {
225	            throw TutorialRefusal(
226	                sentence: "This step goes on by itself once it is done; Next is only on a step "
227	                    + "with nothing to wait for.")
228	        }
229	        advance(by: .next)
230	    }
231	
232	    func skip() throws {
233	        try refuseWhileShowMe()
234	        if finished { throw TutorialRefusal(sentence: "The tutorial is finished.") }
235	        guard currentStep.optional else {
236	            throw TutorialRefusal(sentence: "Only an optional step can be skipped.")
237	        }
238	        advance(by: .skip)
239	    }
240	
241	    func back() throws {
242	        try refuseWhileShowMe()
243	        let target: Int
244	        if finished {
245	            target = index
246	        } else {
247	            guard index > 0 else { throw TutorialRefusal(sentence: "This is the first step.") }
248	            target = index - 1
249	        }
250	        completed.removeAll { $0.step >= target + 1 }
251	        begin(target, .back)
252	    }
253	
254	    // MARK: - The state
255	
256	    /// What the panel offers now, in its order.
257	    var offers: [String] {
258	        var out: [String] = []
259	        if finished || index > 0 { out.append("back") }
260	        if !finished {
261	            let step = currentStep
262	            if !step.showMe.isEmpty { out.append("show_me") }
263	            if step.optional { out.append("skip") }
264	            if step.wait.isEmpty { out.append("next") }
265	        }
266	        out.append("exit")
267	        return out
268	    }
269	
270	    /// The dev tools' answer: where the tutorial is and what it holds.
271	    func state() -> [String: Any] {
272	        let step = currentStep
273	        var reveal: Any = NSNull()
274	        if let shown = step.reveal {
275	            reveal = [
276	                "tab": shown.tab.title.lowercased(),
277	                "sub_tab": shown.subTab.map { $0.rawValue as Any } ?? NSNull(),
278	                "section": shown.section.map { $0 as Any } ?? NSNull(),
279	            ] as [String: Any]
280	        }
281	        var last: Any = NSNull()
282	        if let outcome = lastShowMe {
283	            last = [
284	                "step": outcome.step, "ok": outcome.ok,
285	                "error": outcome.error.map { $0 as Any } ?? NSNull(),
286	                "results": outcome.results, "paths": outcome.paths,
287	            ] as [String: Any]
288	        }
289	        return [
290	            "running": true,
291	            "id": tutorial.id,
292	            "title": tutorial.title,
293	            "step": index + 1,
294	            "steps": tutorial.steps.count,
295	            "text": step.text,
296	            "optional": step.optional,
297	            "wait": !step.wait.isEmpty,
298	            "show_me": !step.showMe.isEmpty,
299	            "offers": offers,
300	            "spotlight": step.spotlight.map { $0 as Any } ?? NSNull(),
301	            "reveal": reveal,
302	            "reveal_refused": revealRefused.map { $0 as Any } ?? NSNull(),
303	            "finished": finished,
304	            "show_me_running": showMeRunning,
305	            "last_show_me": last,
306	            "selection_at_start": baseline.selection.map { Int($0) },
307	            "created": created.map { Int($0) },
308	            "completed": completed.map { ["step": $0.step, "by": $0.by.rawValue] as [String: Any] },
309	        ]
310	    }
311	}
 /// The value at a dotted path of a clip's JSON; absent is `NSNull`.
 static func value(at path: String, in clip: [String: Any]) -> NSObject {
     var here: Any = clip
     for part in path.split(separator: ".") {
         guard let object = here as? [String: Any], let next = object[String(part)] else {
             return NSNull()
         }
         here = next
     }
     return (here as? NSObject) ?? NSNull()
 }

 /// The last handle read and its clips by id: `changed` reads one handle
 /// many times between edits.
 private static var parsed: (handle: ReelProject, clips: [UInt32: [String: Any]])?

 /// The project's `clips`, as the core writes them, by id. Main only.
 static func clipJSON(_ project: ReelProject) -> [UInt32: [String: Any]] {
     if let parsed, parsed.handle === project { return parsed.clips }
     var clips: [UInt32: [String: Any]] = [:]
     if let top = (try? JSONSerialization.jsonObject(with: Data(project.json.utf8)))
         as? [String: Any], let list = top["clips"] as? [[String: Any]]
     {
         for clip in list {
             if let id = (clip["id"] as? NSNumber)?.uint32Value { clips[id] = clip }
         }
     }
     parsed = (project, clips)
     return clips
 }

 /// Lets go of the cached handle, so a closed document's project is not
 /// kept alive; a runner calls it as it goes. Main only.
 static func forgetClipJSON() {
     parsed = nil
 }

 // MARK: - Needs

 /// nil when some clip meets the tutorial's `needs.clip` (or it needs
 /// none); else the one sentence saying what is missing.

